import json,numpy as np
d=json.load(open('/tmp/batch.json'));res=d['results']
scan={x['item']:x['occurrences'] for x in json.load(open('/tmp/scan.json'))['items']}
def agg(a,w0): return w0*a[0]+(1-w0)*(2/3*a[1]+1/3*a[2])
D={}
for m in ['M_new','M_ref']:
    rs=[r for r in res if r['model']==m]
    sl=np.array([x['slice'] for x in rs[0]['detail']]); unc=np.array([scan[x['item']]==0 for x in rs[0]['detail']])
    C=np.array([[1.0 if x['correct'] else 0.0 for x in r['detail']] for r in rs])
    X=np.array([r['reps_acc'][0] for r in rs]); allreps=np.concatenate([r['reps_acc'] for r in rs])
    D[m]=(C,sl,unc,X,allreps)
C,sl,unc,X,allreps=D['M_new']
Y=C[:,unc].mean(1); o=np.argsort(X)
print('X sorted vs Y(unc):'); print(np.round(X[o],3)); print(np.round(Y[o],3))
p=np.polyfit(X,Y,2); print('quad fit',p, 'quad at mu:',np.polyval(p,allreps.mean()), 'E over pooled reps of quad:',np.polyval(p,allreps).mean())
print('pooled reps: mean %.4f sd %.4f skew %.2f min %.3f max %.3f'%(allreps.mean(),allreps.std(ddof=1),((allreps-allreps.mean())**3).mean()/allreps.std()**3,allreps.min(),allreps.max()))
# q5 endpoint se via bootstrap over calls, regression-adjusted
rng=np.random.default_rng(0)
def est(m,w0,idx=None):
    C,sl,unc,X,allreps=D[m]; 
    if idx is not None: C=C[idx];X=X[idx]
    a=[]
    for s in range(3):
        Y=C[:,(sl==s)&unc].mean(1); b=np.cov(Y,X)[0,1]/X.var(ddof=1); a.append(Y.mean()+b*(allreps.mean()-X.mean()))
    return agg(a,w0)
for w0 in [0.15,0.85]:
    bs=[est('M_new',w0,rng.integers(0,20,20))-est('M_ref',w0,rng.integers(0,13,13)) for _ in range(500)]
    print('w0',w0,'diff %.4f boot se %.4f'%(est('M_new',w0)-est('M_ref',w0),np.std(bs)))
"

